{
    public IReadOnlyList<Journey> All { get; } = new List<Journey>
    {
        new() { Id="mysteres", Title="Mystères & énigmes", Question="Qui a construit les pyramides, et que savons-nous vraiment ?", Description="Enquêtes historiques, trésors disparus et phénomènes étranges : sépare les indices solides des légendes qui embellissent l’histoire.", Category="Enquête & mystère", Icon="🔎", WikipediaUrl="https://fr.wikipedia.org/wiki/Pyramides_d%27%C3%89gypte", EnglishUrl="https://en.wikipedia.org/wiki/Egyptian_pyramids", SpanishUrl="https://es.wikipedia.org/wiki/Pir%C3%A1mides_de_Egipto", SecondarySourceName="Smithsonian — Ancient Egypt", SecondarySourceUrl="https://www.si.edu/spotlight/ancient-egypt", Paths=new[]{"Le mystère des pyramides", "Le trésor jamais retrouvé", "Les disparitions célèbres", "Le paranormal à l’épreuve des preuves"}, PathQuestions=new[]{"Que nous apprennent vraiment les traces archéologiques ?", "Comment distinguer une piste d’une rumeur ?", "Pourquoi certaines affaires restent-elles non résolues ?", "Quelle preuve permettrait de trancher ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Pyramides_d%27%C3%89gypte", "https://fr.wikipedia.org/wiki/Chambre_d%27ambre", "https://fr.wikipedia.org/wiki/Disparition", "https://fr.wikipedia.org/wiki/Z%C3%A9t%C3%A9tique"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Egyptian_pyramids", "https://en.wikipedia.org/wiki/Amber_Room", "https://en.wikipedia.org/wiki/Disappearance", "https://en.wikipedia.org/wiki/Skepticism"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Pir%C3%A1mides_de_Egipto", "https://es.wikipedia.org/wiki/C%C3%A1mara_de_%C3%81mbar", "https://es.wikipedia.org/wiki/Desaparici%C3%B3n", "https://es.wikipedia.org/wiki/Escepticismo"}, PathFacts=new[]{"En 2013, une mission dirigée par Pierre Tallet a découvert à Ouadi el-Jarf, sur la mer Rouge, le journal de bord d’un inspecteur nommé Merer, écrit vers 2560 av. J.-C. Il consigne le transport de blocs de calcaire de Tourah jusqu’à Gizeh, la 26e année du règne de Khéops, avec une quarantaine de bateliers sous ses ordres. Selon Tallet, ces pierres étaient très probablement destinées au revêtement extérieur de la grande pyramide.", "Offerte en 1716 par le roi de Prusse Frédéric-Guillaume Ier au tsar Pierre le Grand, la Chambre d’ambre a été démontée par des soldats allemands en 1941, en 36 heures, et emballée dans 27 caisses pour Königsberg. Sa trace se perd ensuite : plusieurs hypothèses circulent, aucune n’est établie. Une reconstitution a été inaugurée en 2003 à Saint-Pétersbourg, après près de trente ans de travaux.", "Amelia Earhart disparaît en juillet 1937 au-dessus du Pacifique, en tentant un tour du monde par l’équateur avec son navigateur Fred Noonan. La Marine américaine a cherché pendant quatre mois, avec une dizaine de navires et une cinquantaine d’avions, sans trouver la moindre trace de l’appareil. L’article précise qu’aucune des hypothèses avancées depuis n’a été prouvée, et qu’une épave annoncée en 2024 près de l’île Howland s’est révélée, sur une image plus nette, n’être qu’une formation rocheuse.", "James Randi a proposé dès 1964 une récompense à quiconque démontrerait un phénomène paranormal. Le prix a atteint un million de dollars et le défi a été clôturé en 2015. Selon Wikipédia en anglais, environ un millier de personnes ont candidaté et aucune n’a réussi."}, PathFactSourceNames=new[]{"Wikipédia — Journal de Merer", "Wikipédia — Chambre d’ambre", "Wikipédia — Amelia Earhart", "Wikipedia (en anglais) — One Million Dollar Paranormal Challenge"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Journal_de_Merer", "https://fr.wikipedia.org/wiki/Chambre_d%27ambre", "https://fr.wikipedia.org/wiki/Amelia_Earhart", "https://en.wikipedia.org/wiki/One_Million_Dollar_Paranormal_Challenge"} },
        new() { Id="popculture", Title="Cinéma, séries & pop culture", Question="Combien de scènes cultes sont inspirées de faits réels ?", Description="Les coulisses des films, les secrets de tournage et les références cachées qui rendent la culture populaire encore plus amusante.", Category="Culture pop", Icon="🎬", WikipediaUrl="https://fr.wikipedia.org/wiki/Culture_populaire", EnglishUrl="https://en.wikipedia.org/wiki/Popular_culture", SpanishUrl="https://es.wikipedia.org/wiki/Cultura_popular", SecondarySourceName="British Film Institute", SecondarySourceUrl="https://www.bfi.org.uk/", Paths=new[]{"Inspiré d’une histoire vraie ?", "Les secrets des effets spéciaux", "Les erreurs scientifiques au cinéma", "Les références cachées"}, PathQuestions=new[]{"Qu’est-ce qui a été changé pour le film ?", "Comment crée-t-on l’impossible à l’écran ?", "Quelle scène défie les lois de la physique ?", "Quel détail est facile à manquer ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Film_biographique", "https://fr.wikipedia.org/wiki/Effets_sp%C3%A9ciaux", "https://fr.wikipedia.org/wiki/Science-fiction", "https://fr.wikipedia.org/wiki/Intertextualit%C3%A9"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Biographical_film", "https://en.wikipedia.org/wiki/Special_effects", "https://en.wikipedia.org/wiki/Science_fiction", "https://en.wikipedia.org/wiki/Allusion"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Pel%C3%ADcula_biogr%C3%A1fica", "https://es.wikipedia.org/wiki/Efectos_especiales", "https://es.wikipedia.org/wiki/Ciencia_ficci%C3%B3n", "https://es.wikipedia.org/wiki/Intertextualidad"}, PathFacts=new[]{"Dans la vraie transmission d’Apollo 13, Jack Swigert dit « Okay, Houston… we’ve had a problem here », puis Jim Lovell répète « Houston, we’ve had a problem ». Le film de 1995 raccourcit la réplique en « Houston, we have a problem », la version devenue célèbre.", "Les dinosaures de Jurassic Park mélangent trois techniques : des images de synthèse d’ILM pour les plans larges, des animatroniques grandeur nature de Stan Winston pour les plans rapprochés, et des essais de go-motion de Phil Tippett, que Spielberg a jugés insatisfaisants pour les scènes en prises de vue réelle.", "Dans Armageddon, l’astéroïde est décrit comme « de la taille du Texas », alors que le plus grand astéroïde potentiellement dangereux connu mesure environ 7 km. Une analyse de 2011 estime qu’il faudrait une bombe environ un milliard de fois plus puissante que la plus grosse jamais testée pour le fendre. Neil deGrasse Tyson a dit que le film viole plus de lois de la physique par minute que tout autre, jusqu’à Moonfall (2022).", "Un cri de douleur enregistré pour Les Aventures du capitaine Wyatt (1951) a été réutilisé dans Star Wars (1977), Les Aventuriers de l’arche perdue (1981) ou Toy Story (1995). Son nom vient du soldat Wilhelm de La Charge sur la rivière rouge (1953), qui le pousse quand une flèche lui transperce la jambe : c’est Ben Burtt qui l’a ainsi baptisé."}, PathFactSourceNames=new[]{"Wikipedia (en anglais) — Houston, we have a problem", "Wikipédia — Jurassic Park (film)", "Wikipedia (en anglais) — Armageddon (1998 film)", "Wikipédia — Cri Wilhelm"}, PathFactSourceUrls=new[]{"https://en.wikipedia.org/wiki/Houston,_we_have_a_problem", "https://fr.wikipedia.org/wiki/Jurassic_Park_(film)", "https://en.wikipedia.org/wiki/Armageddon_(1998_film)", "https://fr.wikipedia.org/wiki/Cri_Wilhelm"} },
        new() { Id="jeux", Title="Jeux de cerveau", Question="Ton cerveau peut-il te faire voir quelque chose qui n’existe pas ?", Description="Illusions d’optique, casse-têtes et biais de jugement : teste tes intuitions avant de découvrir pourquoi elles te jouent parfois des tours.", Category="Défis express", Icon="🧠", WikipediaUrl="https://fr.wikipedia.org/wiki/Illusion_d%27optique", EnglishUrl="https://en.wikipedia.org/wiki/Optical_illusion", SpanishUrl="https://es.wikipedia.org/wiki/Ilusi%C3%B3n_%C3%B3ptica", SecondarySourceName="American Psychological Association — cognition", SecondarySourceUrl="https://www.apa.org/topics/cognitive-bias", Paths=new[]{"Illusions d’optique", "La mémoire, pas si fidèle", "Les biais qui nous piègent", "Petites énigmes de logique"}, PathQuestions=new[]{"Pourquoi deux lignes égales semblent-elles différentes ?", "Un souvenir est-il une copie exacte ?", "Pourquoi croyons-nous si vite ce qui nous arrange ?", "Peux-tu résoudre le problème sans te précipiter ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Illusion_d%27optique", "https://fr.wikipedia.org/wiki/M%C3%A9moire", "https://fr.wikipedia.org/wiki/Biais_cognitif", "https://fr.wikipedia.org/wiki/Logique"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Optical_illusion", "https://en.wikipedia.org/wiki/Memory", "https://en.wikipedia.org/wiki/Cognitive_bias", "https://en.wikipedia.org/wiki/Logic"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Ilusi%C3%B3n_%C3%B3ptica", "https://es.wikipedia.org/wiki/Memoria_(proceso)", "https://es.wikipedia.org/wiki/Sesgo_cognitivo", "https://es.wikipedia.org/wiki/L%C3%B3gica"}, PathFacts=new[]{"Décrite en 1889 par le psychologue Franz Müller-Lyer, l’illusion montre deux segments de même longueur : celui dont les extrémités pointent vers l’intérieur paraît plus long. L’effet se retrouve dans de nombreuses variantes, quelle que soit l’orientation ou la taille apparente, et s’affaiblit seulement un peu avec la répétition.", "Dans l’étude de Loftus et Palmer (1974), 45 étudiants regardent des films d’accidents de voiture puis estiment la vitesse. Selon le verbe de la question, la moyenne change : 32 mph avec « collided », 34 avec « hit each other », 41 avec « smashed each other ». La formulation d’une question posée après coup peut donc reconstruire le souvenir : c’est l’effet de désinformation.", "En 1960, Peter Wason dit à des participants que la suite 2-4-6 obéit à une règle, et leur demande de proposer d’autres suites pour la deviner. La vraie règle est simplement « une suite croissante ». Ils échouent surtout parce qu’ils testent des exemples qui confirment leur idée (11-13-15) et presque jamais ceux qui la contredisent (11-12-19).", "Trois portes cachent une voiture et deux chèvres. Après votre choix, le présentateur ouvre une porte à chèvre : changer de porte vous fait gagner 2 fois sur 3, rester 1 fois sur 3. Quand Marilyn vos Savant a publié la solution dans Parade, elle dit avoir reçu plus de 10 000 lettres, dont plusieurs d’universitaires qui la contestaient. Le résultat suppose que le présentateur sait où est la voiture et ouvre toujours une porte à chèvre."}, PathFactSourceNames=new[]{"Wikipédia — Illusion de Müller-Lyer", "Wikipedia (en anglais) — Elizabeth Loftus", "Wikipédia — Biais de confirmation", "Wikipédia — Problème de Monty Hall"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Illusion_de_M%C3%BCller-Lyer", "https://en.wikipedia.org/wiki/Elizabeth_Loftus", "https://fr.wikipedia.org/wiki/Biais_de_confirmation", "https://fr.wikipedia.org/wiki/Probl%C3%A8me_de_Monty_Hall"} },
        new() { Id="voyages", Title="Voyages & cultures étonnantes", Question="Quelle tradition locale te semblerait la plus étrange ?", Description="Fêtes insolites, habitudes du quotidien et coutumes surprenantes : découvre le monde sans quitter ton canapé, sans caricaturer les cultures.", Category="Ailleurs, autrement", Icon="🌍", WikipediaUrl="https://fr.wikipedia.org/wiki/Patrimoine_culturel_immat%C3%A9riel", EnglishUrl="https://en.wikipedia.org/wiki/Intangible_cultural_heritage", SpanishUrl="https://es.wikipedia.org/wiki/Patrimonio_cultural_inmaterial_de_la_Humanidad", SecondarySourceName="UNESCO — patrimoine culturel immatériel", SecondarySourceUrl="https://ich.unesco.org/", Paths=new[]{"Des fêtes hors du commun", "Des habitudes qui changent selon les pays", "Des plats qui surprennent", "Les règles inattendues de certains lieux"}, PathQuestions=new[]{"Quelle histoire explique cette célébration ?", "Est-ce une règle sociale ou une idée reçue ?", "Pourquoi ce plat est-il important localement ?", "Comment les habitants expliquent-ils cette coutume ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/F%C3%AAte", "https://fr.wikipedia.org/wiki/Patrimoine_culturel_immat%C3%A9riel", "https://fr.wikipedia.org/wiki/Cuisine", "https://fr.wikipedia.org/wiki/Coutume"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Festival", "https://en.wikipedia.org/wiki/Intangible_cultural_heritage", "https://en.wikipedia.org/wiki/Cuisine", "https://en.wikipedia.org/wiki/Custom_(law)"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Fiesta", "https://es.wikipedia.org/wiki/Patrimonio_cultural_inmaterial_de_la_Humanidad", "https://es.wikipedia.org/wiki/Gastronom%C3%ADa", "https://es.wikipedia.org/wiki/Costumbre"}, PathFacts=new[]{"La Tomatina de Buñol (Espagne) a lieu le dernier mercredi d’août. La version la plus courante raconte qu’en 1945 une bousculade pendant un défilé a dégénéré en bagarre, des jeunes attrapant des tomates chez un commerçant voisin ; l’année suivante, ils seraient revenus avec les leurs. Les autorités s’y sont opposées, puis la municipalité a fini par autoriser la bataille en 1959, avec des horaires encadrés par des feux d’artifice. L’article présente d’autres versions de l’origine.", "En France, le pourboire n’est ni requis ni attendu : on arrondit à l’euro supérieur pour une petite addition, jusqu’à 5 % pour une plus grosse. Aux États-Unis, l’usage est de 15 à 20 % de la facture. Au Japon, il n’existe pas de culture du pourboire et en laisser peut créer de la gêne, voire être perçu comme un manque de respect envers les serveurs et les cuisiniers.", "Le surströmming est un hareng de la Baltique suédois, originaire du Norrland, qui fermente dans des récipients ouverts grâce à ses propres enzymes et à des bactéries, puis dans sa boîte, qui se bombe peu à peu. Les premières boîtes de l’année s’ouvrent traditionnellement fin août, et un festival lui est dédié à Alfta depuis 1978. À cause de la pression, on ouvre la conserve dehors, dans une bassine d’eau.", "L’accès à la péninsule du mont Athos est interdit aux femmes, par la loi grecque et par la tradition religieuse. La tradition athonite raconte que la Vierge Marie, poussée vers l’Athos en bateau avec saint Jean l’Évangéliste, a béni la montagne comme son jardin : elle fut consacrée à la Mère de Dieu et interdite à toute autre femme. Les visiteurs, uniquement des hommes, ont besoin d’un permis spécial, le diamonitirion."}, PathFactSourceNames=new[]{"Wikipédia — Tomatina", "Wikipédia — Pourboire", "Wikipédia — Surströmming", "Wikipedia (en anglais) — Mount Athos"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Tomatina", "https://fr.wikipedia.org/wiki/Pourboire", "https://fr.wikipedia.org/wiki/Surstr%C3%B6mming", "https://en.wikipedia.org/wiki/Mount_Athos"} },
        new() { Id="animaux", Title="Animaux extraordinaires", Question="Quel animal possède un super-pouvoir bien réel ?", Description="Camouflage, sens étonnants et stratégies de survie : la nature invente des solutions plus surprenantes que la science-fiction.", Category="Nature incroyable", Icon="🐙", WikipediaUrl="https://fr.wikipedia.org/wiki/Poulpe", EnglishUrl="https://en.wikipedia.org/wiki/Octopus", SpanishUrl="https://es.wikipedia.org/wiki/Octopoda", SecondarySourceName="Smithsonian Ocean — octopuses", SecondarySourceUrl="https://ocean.si.edu/ocean-life/invertebrates/octopus", Paths=new[]{"Les maîtres du camouflage", "Des sens hors normes", "Les stratégies de séduction animale", "Les records du monde vivant"}, PathQuestions=new[]{"Comment cet animal disparaît-il à nos yeux ?", "Que perçoit-il que nous ne percevons pas ?", "Quels comportements servent à attirer un partenaire ?", "Le record est-il confirmé et bien mesuré ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Camouflage", "https://fr.wikipedia.org/wiki/Sens_(physiologie)", "https://fr.wikipedia.org/wiki/S%C3%A9lection_sexuelle", "https://fr.wikipedia.org/wiki/Record_du_monde"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Camouflage", "https://en.wikipedia.org/wiki/Sense", "https://en.wikipedia.org/wiki/Sexual_selection", "https://en.wikipedia.org/wiki/List_of_animal_superlatives"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Camuflaje", "https://es.wikipedia.org/wiki/Sentido_(percepci%C3%B3n)", "https://es.wikipedia.org/wiki/Selecci%C3%B3n_sexual", "https://es.wikipedia.org/wiki/Anexo:Animales_m%C3%A1s_longevos"}, PathFacts=new[]{"Chez les céphalopodes, le pigment est enfermé dans un petit sac élastique que des muscles déforment : en changeant la forme du sac, la peau change de réflectivité ou d’opacité. Chez les poissons, les amphibiens et les reptiles, le pigment se déplace à l’intérieur de la cellule ; chez les céphalopodes, l’effet est comparable mais plus rapide et plus précis. Chez les poulpes, les chromatophores s’activent en vagues, ce qui s’expliquerait par l’activation successive des neurones.", "Sous l’eau, l’ornithorynque ferme hermétiquement les yeux et les oreilles. Il repère ses proies grâce à des électrorécepteurs situés dans la peau de son bec, qui captent le champ électrique produit par les contractions musculaires des animaux. Il compare l’intensité du signal selon l’orientation du bec, ce qui expliquerait ses va-et-vient de la tête pendant la chasse. Son électrolocalisation est la plus sensible de tous les monotrèmes.", "Le jardinier satiné construit une allée entre deux murs de brindilles, longue de 60 à 90 cm, qu’il décore surtout d’objets bleus : fleurs, plumes, mais aussi bouchons, jouets ou Lego. Il peint même les parois intérieures avec un mélange de baies écrasées, de charbon et de salive, appliqué avec des fibres d’écorce en guise de pinceau. La femelle observe en silence et semble évaluer le mâle. Un mâle a été vu plus de 15 ans sur le même berceau.", "Selon l’article, la sterne arctique profite de deux étés par an, un dans chaque hémisphère, et voit plus de lumière que toute autre créature. Côté distances, il cite deux chiffres : 38 000 km par an à un endroit, un trajet pouvant atteindre 70 000 km à un autre. Il n’explique pas comment la distance a été mesurée. Un record de ce genre dépend donc de la méthode de mesure : avant de retenir un chiffre, cherche son protocole. Sur une vie, l’article estime environ 800 000 km pour un individu moyen."}, PathFactSourceNames=new[]{"Wikipédia — Chromatophore", "Wikipédia — Ornithorynque", "Wikipédia — Jardinier satiné", "Wikipédia — Sterne arctique"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Chromatophore", "https://fr.wikipedia.org/wiki/Ornithorynque", "https://fr.wikipedia.org/wiki/Jardinier_satin%C3%A9", "https://fr.wikipedia.org/wiki/Sterne_arctique"} },
        new() { Id="inventions", Title="Inventions folles & échecs célèbres", Question="Une invention ratée peut-elle changer le monde ?", Description="Objets absurdes, grandes idées mal lancées et découvertes accidentelles : les ratés racontent souvent une histoire passionnante.", Category="Idées inattendues", Icon="💡", WikipediaUrl="https://fr.wikipedia.org/wiki/Post-it", EnglishUrl="https://en.wikipedia.org/wiki/Post-it_note", SpanishUrl="https://es.wikipedia.org/wiki/Post-it", SecondarySourceName="Encyclopaedia Britannica — invention", SecondarySourceUrl="https://www.britannica.com/technology/invention", Paths=new[]{"Les inventions les plus improbables", "Les échecs commerciaux mémorables", "Les découvertes accidentelles", "Les objets qui ont changé le quotidien"}, PathQuestions=new[]{"Quel besoin l’inventeur voulait-il résoudre ?", "Pourquoi le public n’a-t-il pas suivi ?", "Quelle part revient au hasard et quelle part au travail ?", "Comment cet objet a-t-il changé nos habitudes ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Invention", "https://fr.wikipedia.org/wiki/%C3%89chec", "https://fr.wikipedia.org/wiki/S%C3%A9rendipit%C3%A9", "https://fr.wikipedia.org/wiki/Histoire_des_techniques"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Invention", "https://en.wikipedia.org/wiki/Failure", "https://en.wikipedia.org/wiki/Serendipity", "https://en.wikipedia.org/wiki/History_of_technology"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Invento", "https://es.wikipedia.org/wiki/Historia_de_la_tecnolog%C3%ADa", "https://es.wikipedia.org/wiki/Serendipia", "https://es.wikipedia.org/wiki/Historia_de_la_tecnolog%C3%ADa"}, PathFacts=new[]{"Les prix Ig Nobel, créés en 1991 par la revue Annals of Improbable Research (Marc Abrahams), récompensent des recherches qui font d’abord rire, puis réfléchir. En 2006, Basile Audoly et Sébastien Neukirch ont été primés pour une étude sur les spaghettis. André Geim a reçu un Ig Nobel pour avoir fait léviter une grenouille, puis le prix Nobel de physique en 2010.", "Lancée en 1957, l’Edsel de Ford n’a été produite que pour les millésimes 1958 à 1960. L’article avance plusieurs causes : un lancement pendant une brève récession, des voitures peu fiables au début (on disait que EDSEL signifiait « Every Day Something Else Leaks »), un positionnement trop proche de Mercury, une liste d’options excessive et confuse, et une étude de marché qui aurait été biaisée pour plaire aux dirigeants.", "Fleming a redécouvert la pénicilline par accident en 1928, puis a passé des années à tenter de la purifier. En 1940, une équipe britannique avec Howard Florey, Ernst Chain et Norman Heatley parvient à en produire assez pour tuer les bactéries d’un organisme vivant ; elle est utilisée chez l’humain à partir de 1941. En 1942, une usine d’Eli Lilly peut produire 40 milliards d’unités par mois. Le hasard a lancé l’histoire, le travail l’a rendue utile.", "Bernard Sadow dépose en 1970 un brevet de valise à roulettes, obtenu en 1972. Des brevets plus anciens (1887, 1945, 1949) n’ont pas abouti commercialement. La valise verticale à deux roues, le Rollaboard, est inventée en 1987 par un pilote, Robert Plath, qui la vend d’abord à des équipages. Sadow attribuait la lenteur de l’adoption à un « truc de macho » ; d’autres citent l’abondance de porteurs."}, PathFactSourceNames=new[]{"Wikipédia — Prix Ig Nobel", "Wikipédia — Edsel", "Wikipédia — Pénicilline", "Wikipedia (en anglais) — Wheeled luggage"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Prix_Ig_Nobel", "https://fr.wikipedia.org/wiki/Edsel", "https://fr.wikipedia.org/wiki/P%C3%A9nicilline", "https://en.wikipedia.org/wiki/Wheeled_luggage"} },
        new() { Id="vraioufaux", Title="Incroyable… mais vrai ?", Question="Vrai ou faux : utilisons-nous seulement 10 % de notre cerveau ?", Description="Records, idées reçues, photos trompeuses et faits scientifiques étonnants. Devine d’abord, puis vérifie ce que les sources permettent vraiment d’affirmer.", Category="Vrai / faux", Icon="🧐", WikipediaUrl="https://fr.wikipedia.org/wiki/Neuromythe", EnglishUrl="https://en.wikipedia.org/wiki/Ten_percent_of_the_brain_myth", SpanishUrl="https://es.wikipedia.org/wiki/Mito_del_10%25_del_cerebro", SecondarySourceName="Harvard Health Publishing — the 10% myth", SecondarySourceUrl="https://www.health.harvard.edu/mind-and-mood/you-only-use-10-percent-of-your-brain", Paths=new[]{"Les mythes sur le corps humain", "Les records vraiment vérifiés", "Photos et vidéos trompeuses", "Les sciences qui semblent impossibles"}, PathQuestions=new[]{"Que disent les neurosciences sur cette affirmation ?", "Qui a homologué ce record et selon quelles règles ?", "Quel indice révèle une manipulation ?", "Quelle expérience permet de tester cette idée ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Neuromythe", "https://fr.wikipedia.org/wiki/Record_du_monde", "https://fr.wikipedia.org/wiki/D%C3%A9sinformation", "https://fr.wikipedia.org/wiki/M%C3%A9thode_scientifique"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Human_body", "https://en.wikipedia.org/wiki/World_record", "https://en.wikipedia.org/wiki/Disinformation", "https://en.wikipedia.org/wiki/Scientific_method"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Cuerpo_humano", "https://es.wikipedia.org/wiki/R%C3%A9cord_mundial", "https://es.wikipedia.org/wiki/Desinformaci%C3%B3n", "https://es.wikipedia.org/wiki/M%C3%A9todo_cient%C3%ADfico"}, PathFacts=new[]{"L’imagerie cérébrale (TEP, IRMf) montre que toutes les régions du cerveau sont actives, plus ou moins selon le moment, et même pendant le sommeil. Le cerveau représente environ 2 % du poids du corps et peut consommer jusqu’à 20 % de son énergie. Même une petite lésion peut avoir de lourdes conséquences.", "Le record du monde du 100 m est de 9 s 58, établi par Usain Bolt le 16 août 2009 en finale des championnats du monde de Berlin. Les records sont homologués par World Athletics : seuls les temps mesurés au chronométrage électronique sont validés, et le vent compte (2,0 m/s de vent arrière est présenté comme la limite autorisée ; des performances à 2,2 et 4,1 m/s n’ont pas été validées).", "En 1917 et 1920, deux cousines, Elsie Wright et Frances Griffiths, ont pris cinq photos de « fées » à Cottingley. Arthur Conan Doyle les a défendues dans The Strand Magazine en 1920. Un expert avait jugé les négatifs authentiques, faute de trace de maquette ; des techniciens de Kodak n’avaient rien trouvé mais refusaient de les certifier. En 1983, Elsie a avoué dans une lettre que c’étaient des découpages de carton, tenus par des épingles à chapeau.", "L’expérience d’Alain Aspect, réalisée en 1982, a violé les inégalités de Bell, que la physique classique devrait toujours respecter. Cela exclut, selon l’article, les théories à variables cachées locales et déterministes, mais pas les théories déterministes non locales, comme celle de de Broglie-Bohm. L’interprétation de ces résultats reste un débat ouvert."}, PathFactSourceNames=new[]{"Wikipedia (en anglais) — Ten percent of the brain myth", "Wikipédia — Record du monde du 100 mètres", "Wikipédia — Fées de Cottingley", "Wikipédia — Inégalités de Bell"}, PathFactSourceUrls=new[]{"https://en.wikipedia.org/wiki/Ten_percent_of_the_brain_myth", "https://fr.wikipedia.org/wiki/Record_du_monde_du_100_m%C3%A8tres", "https://fr.wikipedia.org/wiki/F%C3%A9es_de_Cottingley", "https://fr.wikipedia.org/wiki/In%C3%A9galit%C3%A9s_de_Bell"} },
        new() { Id="relations", Title="Amour, relations & comportements", Question="Pourquoi un simple message peut-il être mal interprété ?", Description="Les gestes, les émotions et les malentendus du quotidien vus à travers la psychologie — avec nuance, sans prétendre lire dans les pensées.", Category="Psychologie du quotidien", Icon="💬", WikipediaUrl="https://fr.wikipedia.org/wiki/Communication_interpersonnelle", EnglishUrl="https://en.wikipedia.org/wiki/Interpersonal_communication", SpanishUrl="https://es.wikipedia.org/wiki/Comunicaci%C3%B3n_interpersonal", SecondarySourceName="American Psychological Association — relationships", SecondarySourceUrl="https://www.apa.org/topics/relationships", Paths=new[]{"Les pièges des messages écrits", "Comment naît l’attirance ?", "Les gestes et leur contexte", "Ce que la psychologie sait vraiment"}, PathQuestions=new[]{"Pourquoi manque-t-il des indices dans un texto ?", "Quels facteurs peuvent contribuer à l’attirance ?", "Un geste a-t-il le même sens partout ?", "Quelles conclusions sont solides et lesquelles restent discutées ?"}, PathSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Communication_%C3%A9crite", "https://fr.wikipedia.org/wiki/Attirance_interpersonnelle", "https://fr.wikipedia.org/wiki/Communication_non_verbale", "https://fr.wikipedia.org/wiki/Psychologie"}, PathSourceUrlsEnglish=new[]{"https://en.wikipedia.org/wiki/Written_communication", "https://en.wikipedia.org/wiki/Interpersonal_attraction", "https://en.wikipedia.org/wiki/Nonverbal_communication", "https://en.wikipedia.org/wiki/Psychology"}, PathSourceUrlsSpanish=new[]{"https://es.wikipedia.org/wiki/Comunicaci%C3%B3n_escrita", "https://es.wikipedia.org/wiki/Atracci%C3%B3n_interpersonal", "https://es.wikipedia.org/wiki/Comunicaci%C3%B3n_no_verbal", "https://es.wikipedia.org/wiki/Psicolog%C3%ADa"}, PathFacts=new[]{"Un texto ne transmet que les mots. On cite souvent la « règle des 7 % – 38 % – 55 % » (mots, voix, corps) pour dire qu’ils ne comptent presque pas, mais elle vient de deux études de 1967 sur des mots isolés comme « cher » ou « terrible », et ne vaut que pour des sentiments ou attitudes ambigus. Mehrabian lui-même précise qu’elle ne s’applique pas en dehors de ce cas : c’est, selon l’article, l’erreur la plus fréquente à son sujet.", "En 1968, Robert Zajonc présente à des participants des mots de sept lettres sans signification (comme « iktitaf » ou « kadirga »), annoncés comme turcs, entre 0 et 25 fois. Plus un mot a été vu, plus il est jugé positivement. La répétition augmente la fluence perceptive, c’est-à-dire la facilité à traiter le stimulus, et cette facilité nourrit les sentiments positifs : la familiarité favorise l’appréciation.", "Le geste « OK » n’a pas le même sens partout. En France, il peut vouloir dire « zéro » ou « ça ne vaut rien », sens plus répandu dans le sud, alors que le sens positif domine dans le nord. Au Japon, il évoque l’argent. En Turquie, il est considéré comme très insultant. Dans les années 1950, Richard Nixon l’a fait des deux mains à son arrivée à São Paulo, par bienveillance, et la foule s’est offusquée.", "Dans le grand projet de réplication en psychologie décrit par l’article, 36 % des études testées ont obtenu des résultats significatifs, contre 97 % des recherches initiales, et l’effet mesuré était en moyenne deux fois plus petit. Selon l’article, la moitié des recherches en psychologie cognitive et environ trois quarts de celles en psychologie sociale n’ont pas pu être reproduites."}, PathFactSourceNames=new[]{"Wikipédia — Albert Mehrabian", "Wikipédia — Effet de simple exposition", "Wikipedia (en anglais) — OK gesture", "Wikipédia — Crise de la reproductibilité"}, PathFactSourceUrls=new[]{"https://fr.wikipedia.org/wiki/Albert_Mehrabian", "https://fr.wikipedia.org/wiki/Effet_de_simple_exposition", "https://en.wikipedia.org/wiki/OK_gesture", "https://fr.wikipedia.org/wiki/Crise_de_la_reproductibilit%C3%A9"} }
    };

